            n_var=n, n_obj=1, xl=np.full(n, -1.0), xu=np.full(n, 1.0)
        )
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def optimize(
    evaluator: Evaluator, evaluations: int, seed: int
) -> np.ndarray:
    algorithm = PSO(
        pop_size=24,
        w=0.75,
        c1=0.8,
        c2=0.8,
        adaptive=True,
    )
    result = minimize(
        Problem(evaluator),
        algorithm,
        termination=("n_eval", evaluations),
        seed=seed,
        verbose=False,
    )
    best = np.asarray(
        result.X if result.X is not None else evaluator.extract_active(),
        dtype=float,
    )
    evaluator.insert(best)
    return best


